"""Read-only alerts of one astronaut. Alerts are generated by the backend."""

from typing import Annotated

from fastapi import APIRouter, Query

from app.config import SCHEMA_VERSION
from app.database import repository
from app.models.fields import AlertStatus
from app.models.responses import AlertListMeta, AlertListResponse
from app.routes.common import (
    AsOf,
    AstronautId,
    FromDay,
    Limit,
    Offset,
    ToDay,
    database,
    documented,
)
from app.services import views

router = APIRouter(prefix="/api/astronauts/{astronaut_id}/alerts", tags=["alerts"])


@router.get(
    "",
    response_model=AlertListResponse,
    responses=documented(("alerts_not_implemented_is_not_an_all_clear",)),
)
def list_alerts(
    astronaut_id: AstronautId,
    limit: Limit = 100,
    offset: Offset = 0,
    from_day: FromDay = None,
    to_day: ToDay = None,
    as_of: AsOf = None,
    status: Annotated[
        AlertStatus | None, Query(description="Only alerts in this state.")
    ] = None,
) -> AlertListResponse:
    """Alerts newest first. Check `meta.evaluation_status` before reading `data`.

    While the status is `not_implemented` the list is empty because nothing
    was evaluated, not because no alert applies.
    """
    with database() as conn:
        astronaut = repository.require_astronaut(conn, astronaut_id)
        views.check_day_range(astronaut, from_day, to_day)
        cutoff = views.resolve_as_of(conn, astronaut, as_of)
        evaluation_status, alerts = views.alert_view(conn, astronaut, cutoff)
    alerts = [
        alert
        for alert in views.visible(alerts, cutoff, from_day, to_day)
        if status is None or alert.status == status
    ]
    return AlertListResponse(
        data=views.page(alerts, limit, offset),
        meta=AlertListMeta(
            schema_version=SCHEMA_VERSION,
            as_of=cutoff,
            total=len(alerts),
            limit=limit,
            offset=offset,
            evaluation_status=evaluation_status,
        ),
    )
